(* [comment removed for export] *)
Definition ARHEAPQ (s : ast) (XC XB : list Z) (LB : list (Z * Z)) (m : mem) : Prop :=
  AREPQ s XC XB m /\ List.NoDup LB /\ (forall b, In b LB <-> In b (alb s)).
Lemma ARHEAP_of_Q : forall s LB m, ARHEAPQ s [] [] LB m -> qbounds (a_st s) -> ARHEAP s LB m.
Proof. intros s LB m (R & ND & LBs) B. split; [exact (AREP_of_AREPQ s m R B)| exact (conj ND LBs)]. Qed.
Lemma ARHEAPQ_of : forall s LB m, ARHEAP s LB m -> ARHEAPQ s [] [] LB m.
Proof. intros s LB m (R & ND & LBs). split; [exact (AREPQ_of_AREP s m R)| exact (conj ND LBs)]. Qed.

Ltac zlets := repeat match goal with H := _ |- _ => subst H end.

Section FreeAppMid.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (s : ast) (LB : list (Z * Z)) (d : depot) (lo : Z) (CH : list (Z * Z)) (ch : chunk) (bs sbs : list byte).

  Let st := a_st s.
  Let TH := a_thr s.
  Let CTX := a_ctx s.
  Let sb := a_sb s.
  Let U := ch_user_beg ch.
  Let size := ch_used ch.
